body .callout[data-callout*="svg-vintage3"]  {
    --callout-icon: none;
	color: var(--lw);
	background-image: var(--gdj-vintage3);
	background-size: 100% auto;
	background-position: 50% 0%;
	background-repeat: repeat;
}

.whim-border-vintage3 {
	border-style: solid;
	border-width: 10px;
	border-color: color-mix(in srgb, white, transparent 70%);
	border-image: var(--gdj-vintage3) 20;
}

.whim-border-vintage3-layer { 
	border-style: solid;
	border-width: 1px;
	border-color: color-mix(in srgb, white, transparent 70%);
	border-image: var(--gdj-vintage3);
	border-image-width: auto;
	border-image-outset: 0 0 600 0;
	border-image-repeat: repeat;
}

.whim-hr-vintage3 {
	--hr-svg: var(--gdj-vintage3);
}

.whim-bg-stamp-vintage3 {
	--stamp-svg: var(--gdj-vintage3);
}

.whim-mask-vintage3 {
	-webkit-mask-image: var(--gdj-vintage3), radial-gradient(black 50%, color-mix(in srgb, black, transparent 65%) 70%, color-mix(in srgb, black, transparent 100%) 90%);
}
.whim-mask-vintage3-less {
	-webkit-mask-image: var(--gdj-vintage3), radial-gradient(black 50%, color-mix(in srgb, black, transparent 50%) 70%);
}
.whim-mask-vintage3-fade {
	-webkit-mask-image: var(--gdj-vintage3), linear-gradient(black 65%, transparent 90%);
}
.whim-mask-vintage3-fademore {
	-webkit-mask-image: var(--gdj-vintage3), linear-gradient(black 35%, transparent 65%);
}
.whim-mask-vintage3-simple {
	-webkit-mask-image: var(--gdj-vintage3), linear-gradient(color-mix(in srgb, black, transparent 25%) 25%, color-mix(in srgb, black, transparent 50%) 75%);
}